-- UFO Target Practice is now "Cosmic Blast!": a 3D arcade game that flies past all eight planets, Mercury to Neptune,
-- with aliens that shoot back, radar drones that jam your laser, and a spinning black hole between planets.
-- The id (game-ufo), slug and page address stay the same, so existing links keep working.
-- Run once in the Supabase SQL Editor (safe to run again).
update games set data = data || $j${"summary": "Fly past all eight planets, from Mercury to Neptune! Blast flying saucers, dodge alien fire, and dive through a spinning black hole to each new world.", "rules": ["Each planet is one level: score its points goal in 60 seconds to fly on to the next one, from Mercury out to Neptune.", "Move the mouse to aim, and click (or hold the button down) to fire. On a phone or tablet, drag to aim and tap to fire. Arrow keys or WASD steer and Space fires.", "Blue saucers score 1, green score 2, red score 3. New alien craft join on later planets and are worth more.", "From Earth on, some aliens shoot back. Dodge their shots or blast them: lose all 3 shields and you try that planet again.", "From Jupiter on, radar drones send out rings that jam your laser for a moment. Steer out of the way, or zap the drone first.", "Reach the goal and a spinning black hole pulls you through to the next planet, with a fun fact about it.", "Press 1, 2 or 3 (or the laser buttons) to switch lasers. The planets you reach and your best scores are kept on this device.", "Hits and misses add up to an efficiency score — tap \"what's this?\" to see how it's worked out.", "Sound is on: press the speaker button to turn it off."], "minutes": 10, "title": "Cosmic Blast!", "vocabExample": "In Cosmic Blast!, every shot that hits raises your efficiency score. Aim before you fire!"}$j$::jsonb
  || jsonb_build_object('cover', (data->'cover') || jsonb_build_object('alt', $a$A white spaceship flies past Saturn and its rings, firing at flying saucers and a glowing radar drone in Cosmic Blast!$a$::text)),
  updated_at = now()
where id = 'game-ufo';
